/**
 * Generates a seamlessly-tileable green felt texture (256×256 PNG) using an
 * SVG feTurbulence filter rasterised by sharp.  Run from the ui/ directory:
 *   npm run build:felt
 *
 * NOTE: the committed felt-tile.png was generated by an AI image model and
 * looks more authentic than this procedural version.  Running this script
 * will overwrite it with the procedural output.  Only do so if the AI tile
 * is lost or you want to iterate on the procedural parameters.
 */
import sharp from "sharp";
import { writeFileSync } from "fs";
import { fileURLToPath } from "url";
import path from "path";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT = path.join(__dirname, "../public/assets/felt-tile.png");

const SIZE = 256;

// Two noise layers composited in the filter graph:
//   1. Directional fiber layer: high y-frequency, low x-frequency → long horizontal-ish fibers
//   2. Fine surface grain: isotropic high-frequency noise for the short-pile fuzz
// Base colour #1d6b35 matches the richer casino-green visible in the reference image.
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${SIZE}" height="${SIZE}">
  <defs>
    <filter id="felt" x="0%" y="0%" width="100%" height="100%" color-interpolation-filters="linearRGB">
      <!-- Long felt fibers: anisotropic noise (high y-freq, low x-freq = horizontal grain) -->
      <feTurbulence type="fractalNoise" baseFrequency="0.07 0.6"
                    numOctaves="4" seed="17" stitchTiles="stitch"
                    result="fibers"/>
      <!-- Fine surface fuzz: isotropic high-frequency grain -->
      <feTurbulence type="fractalNoise" baseFrequency="0.8"
                    numOctaves="2" seed="3" stitchTiles="stitch"
                    result="grain"/>
      <!-- Blend the two noise layers (screen lifts midtones slightly) -->
      <feBlend in="fibers" in2="grain" mode="screen" result="combined"/>
      <!-- Desaturate to greyscale -->
      <feColorMatrix type="saturate" values="0" in="combined" result="gray"/>
      <!-- Gentle contrast: slope 1.5 keeps midtones; less crushing than the original 2.0 -->
      <feComponentTransfer in="gray" result="contrast">
        <feFuncR type="linear" slope="1.5" intercept="-0.28"/>
        <feFuncG type="linear" slope="1.5" intercept="-0.28"/>
        <feFuncB type="linear" slope="1.5" intercept="-0.28"/>
      </feComponentTransfer>
      <!-- Multiply: darkens the base where fibers shadow; never brightens -->
      <feBlend in="SourceGraphic" in2="contrast" mode="multiply"/>
    </filter>
  </defs>
  <rect width="${SIZE}" height="${SIZE}" fill="#1d6b35" filter="url(#felt)"/>
</svg>`;

const buf = await sharp(Buffer.from(svg))
  .png({ compressionLevel: 9 })
  .toBuffer();

writeFileSync(OUT, buf);
console.log(`Wrote ${OUT} (${buf.length} bytes)`);
